/// Returns true if `x` appears in the slice `a`.
fn is_in_array(a: &[i32], x: i32) -> bool {
    for &item in a {
        if item == x {
            return true;
        }
    }
    false
}

/// Returns true if `x` appears in the vector `v`.
fn contains(v: &Vec<i32>, x: i32) -> bool {
    // Reuse `is_in_array` on the underlying slice
    is_in_array(v.as_slice(), x)
}

/// Constructs and returns a vector containing all integers that
/// appear in `a` but do *not* appear in `b`, with no duplicates.
fn remove_elements(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut result = Vec::new();
    for &item in a {
        // Include `item` only if it's not in `b` and not already in `result`
        if !is_in_array(b, item) && !contains(&result, item) {
            result.push(item);
        }
    }
    result
}

